sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var patientbill = new BillingUtils();

    var amount = patientbill.gettotalamount('0214c8f093626610ec38b2ddfaba105e');
    gs.print(amount.u_total_amount);
    //gs.print('------------------------------------------------');


    var overduestatus = patientbill.getstatus('BLG0001026');
    gs.print(overduestatus);
    var overduestatus = patientbill.getstatus('BLG0001029');
    gs.print(overduestatus);
    //gs.print('------------------------------------------------');


    var records = patientbill.getbillingdetails('BLG0001026');
    gs.print("Billing ID: " + records.number);
    gs.print("Patient ID: " + records.u_patient_id.getDisplayValue());
    gs.print("Total Amount: " + records.u_total_amount);
    gs.print("Current Status: " + records.u_status);
    //gs.print('------------------------------------------------');


    var details = patientbill.getdetailsbypatient('076000fc93226610ec38b2ddfaba1073');
    while (details.next()) {
        gs.print("Billing ID: " + details.number);
        gs.print("Patient ID: " + details.u_patient_id.getDisplayValue());
        gs.print("Total Amount: " + details.u_total_amount);
        gs.print("Current Status: " + details.u_status);
    }


})(current, previous);
